const form=document.querySelector('#enquiry-form');
const dateField=form.elements.date;
const today=new Date();dateField.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
document.querySelectorAll('[data-package]').forEach(button=>button.addEventListener('click',()=>{form.elements.package.value=button.dataset.package;document.querySelector('#enquire').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});form.elements.name.focus({preventScroll:true});}));
form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);const name=String(data.get('name')).trim(),location=String(data.get('location')).trim();if(!name||!location){const input=!name?form.elements.name:form.elements.location;input.setCustomValidity('Please enter a value, not just spaces.');input.reportValidity();input.addEventListener('input',()=>input.setCustomValidity(''),{once:true});return;}document.querySelector('#message').value=`Hi GEES CHILLS! I’d like to enquire about a package.\n\nName: ${name}\nEvent: ${data.get('package')}\nDate: ${data.get('date')}\nExpected guests: ${data.get('guests')}\nLocation: ${location}${String(data.get('notes')).trim()?'\nNotes: '+String(data.get('notes')).trim():''}\n\nPlease let me know the available options and quote.`;document.querySelector('#result').hidden=false;document.querySelector('#copy-status').textContent='Message prepared. Nothing has been sent.';document.querySelector('#message').focus();});
document.querySelector('#copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#message').value);document.querySelector('#copy-status').textContent='Copied. Paste it into your conversation with GEES CHILLS.';}catch{document.querySelector('#message').select();document.querySelector('#copy-status').textContent='Select and copy the message above using your device’s copy command.';}});
